"""Minimal MCP server exposing G1 read-only state APIs.

Three generic tools instead of one tool per getter: the agent discovers the
API surface at runtime from pybind docstrings rather than from hardcoded
schemas.  Runs unchanged on the PC (x86_64) or on the robot Orin (aarch64);
only the embosa IP config differs.

    pip install "mcp>=2"

Launch: the SDK's setup.sh puts its own OpenSSL ahead of the system one, which
breaks `cryptography` (and so the mcp package) with an "Unknown OpenSSL error".
Preload the system libs instead of sourcing setup.sh:

    SDK=/opt/galbot/galbot_sdk/linux-x86_64-gcc940
    LD_LIBRARY_PATH=$SDK/lib PYTHONPATH=$SDK/lib/python \
    LD_PRELOAD=/usr/lib/x86_64-linux-gnu/libcrypto.so.3:/usr/lib/x86_64-linux-gnu/libssl.so.3 \
    python galbot_mcp_state.py
"""

import json

import galbot_sdk
from galbot_sdk.g1 import GalbotRobot
from mcp.server.mcpserver import MCPServer

server = MCPServer("galbot-g1-state")

# Introspect the pybind base class: the g1 wrapper proxies via __getattr__ and
# so reports no members of its own.
_BASE = galbot_sdk.GalbotRobot
_SKIP = {"get_instance"}  # factory, not state
READONLY = sorted(
    n for n in dir(_BASE)
    if n.startswith(("get_", "is_", "check_")) and n not in _SKIP
)

_robot = None


def _get_robot():
    global _robot
    if _robot is None:
        _robot = GalbotRobot()
        if not _robot.init():
            raise RuntimeError("GalbotRobot.init() failed, check embosa IP config")
    return _robot


def _shrink(value, budget=4096):
    """Keep binary blobs (images, point clouds) out of the context window."""
    if isinstance(value, (bytes, bytearray)):
        return f"<{len(value)} bytes, not inlined>"
    if isinstance(value, dict):
        return {k: _shrink(v, budget) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        if len(value) > 64:
            return [_shrink(v, budget) for v in value[:64]] + [f"...{len(value) - 64} more"]
        return [_shrink(v, budget) for v in value]
    return value


@server.tool()
def list_state_apis() -> list[str]:
    """List every read-only robot state API. Start here."""
    return READONLY


@server.tool()
def describe_api(name: str) -> str:
    """Show one state API's signature and return structure. Call before get_state."""
    if name not in READONLY:
        return f"error: unknown read-only API {name!r}"
    # pybind11 puts the signature on the first line of __doc__;
    # inspect.signature() raises on these builtins.
    return getattr(_BASE, name).__doc__ or "(no docstring)"


@server.tool()
def get_state(name: str, kwargs: dict | None = None) -> str:
    """Call a read-only state API. Args come from describe_api."""
    if name not in READONLY:
        return f"error: {name!r} is not a read-only API"
    result = getattr(_get_robot(), name)(**(kwargs or {}))
    return json.dumps(_shrink(result), default=str, ensure_ascii=False)[:8000]


if __name__ == "__main__":
    server.run()
